"""Editable formula workbook, authored as standard OOXML without paid tooling."""
from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
from xml.sax.saxutils import escape
import json
root=Path(__file__).resolve().parents[1]
scenarios=json.loads((root/'charts/scenarios.json').read_text())['scenarios']
ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'
def cell(address,value,style=0,formula=None):
    if formula:return f'<c r="{address}" s="{style}"><f>{escape(formula)}</f><v>{value}</v></c>'
    if isinstance(value,str):return f'<c r="{address}" s="{style}" t="inlineStr"><is><t>{escape(value)}</t></is></c>'
    return f'<c r="{address}" s="{style}"><v>{value}</v></c>'
labels={1:'STEPLOCK / ILLUSTRATIVE ECONOMICS — NOT MEASURED ROI',2:'Editable assumptions',3:'Workstations',4:'Errors per workstation per week',5:'Early detection rate (hypothetical)',6:'Rework minutes avoided per early incident',7:'Operating weeks per year',8:'Labor value / hour (INR)',9:'Material avoided / early incident (INR)',10:'Subscription / station / month (INR)',11:'One-time setup (INR)',13:'Computed annual outcomes',14:'Incidents caught early',15:'Potential labor hours saved',16:'Potential labor value (INR)',17:'Potential material value (INR)',18:'Potential gross annual value (INR)',19:'Annual subscription (INR)',20:'Total first-year assumed cost (INR)',21:'First-year net potential value (INR)',23:'All inputs hypothetical. Excludes customer hardware, workflow-change labor and unmodeled costs.',24:'Potential savings require real avoided work and materials; do not double-count.',25:'Negative conservative economics are intentionally preserved. This is not a customer forecast.'}
rows=[]
for row,label in labels.items():
    cells=[cell(f'A{row}',label,1 if row in [1,2,13] else 0)]
    if row==2:cells += [cell(f'{col}2',s['name'],1) for col,s in zip('BCD',scenarios)]
    for col,s in zip('BCD',scenarios):
        inputs={3:s['stations'],4:s['errors'],5:s['rate'],6:s['minutes'],7:s['weeks'],8:s['labor'],9:s['material'],10:1500,11:20000}
        formulas={14:(f'{col}3*{col}4*{col}5*{col}7',s['incidents']),15:(f'{col}14*{col}6/60',s['hours']),16:(f'{col}15*{col}8',s['labor_savings']),17:(f'{col}14*{col}9',s['material_savings']),18:(f'SUM({col}16:{col}17)',s['gross_savings']),19:(f'{col}3*{col}10*12',s['subscription']),20:(f'{col}19+{col}11',92000),21:(f'{col}18-{col}20',s['net_first_year'])}
        if row in inputs:cells.append(cell(f'{col}{row}',inputs[row],3 if row==5 else 2))
        if row in formulas:cells.append(cell(f'{col}{row}',formulas[row][1],4,formulas[row][0]))
    rows.append(f'<row r="{row}" ht="24" customHeight="1">'+''.join(cells)+'</row>')
sheet=f'<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="{ns}"><sheetViews><sheetView workbookViewId="0"><pane ySplit="2" topLeftCell="A3" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="59" customWidth="1"/><col min="2" max="4" width="22" customWidth="1"/></cols><sheetData>{"".join(rows)}</sheetData></worksheet>'
scale_rows=[['STEPLOCK / HYPOTHETICAL SCALE — NOT TAM'],['Assumption','Value'],['Eligible paying factories',1000],['Stations per factory',2],['Monthly fee per station (INR)',3000],['Months',12],['Potential annual recurring revenue (INR)',72000000],['Eligible accounts, price and conversion all need validation.']]
scale_xml=[]
for i,row in enumerate(scale_rows,1):
    cells=[cell(f'A{i}',row[0],1 if i<3 else 0)]
    if len(row)>1:cells.append(cell(f'B{i}',row[1],4 if i==7 else 2,'B3*B4*B5*B6' if i==7 else None))
    scale_xml.append(f'<row r="{i}" ht="25" customHeight="1">'+''.join(cells)+'</row>')
scale=f'<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="{ns}"><cols><col min="1" max="1" width="65" customWidth="1"/><col min="2" max="2" width="24" customWidth="1"/></cols><sheetData>{"".join(scale_xml)}</sheetData></worksheet>'
styles=f'''<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="{ns}"><numFmts count="1"><numFmt numFmtId="164" formatCode="0%"/></numFmts><fonts count="4"><font><sz val="12"/><name val="Calibri"/></font><font><b/><sz val="12"/><color rgb="FF0F3E68"/><name val="Calibri"/></font><font><sz val="12"/><color rgb="FF9C5B00"/><name val="Calibri"/></font><font><sz val="12"/><color rgb="FF0072C6"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="5"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0"/><xf numFmtId="164" fontId="2" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="0" fontId="3" fillId="0" borderId="0" xfId="0"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'''
parts={'[Content_Types].xml':'''<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>''','_rels/.rels':'''<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>''','xl/workbook.xml':f'''<workbook xmlns="{ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Station economics" sheetId="1" r:id="rId1"/><sheet name="Scale sensitivity" sheetId="2" r:id="rId2"/></sheets><calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>''','xl/_rels/workbook.xml.rels':'''<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>''','xl/styles.xml':styles,'xl/worksheets/sheet1.xml':sheet,'xl/worksheets/sheet2.xml':scale}
with ZipFile(root/'STEPLOCK_Illustrative_Economics.xlsx','w',ZIP_DEFLATED) as z:
    for name,content in parts.items():z.writestr(name,content)
print(json.dumps({'model':'hypothetical','scenarios':[(s['name'],s['hours'],s['gross_savings'],s['net_first_year']) for s in scenarios],'editable_formula_count':25}))
